let result = $input.first()?.json ?? {};
if (result.body !== undefined) result = result.body;
if (result.data !== undefined && !Array.isArray(result)) result = result.data;

const row = Array.isArray(result) ? result[0] : result;
if (!row || typeof row !== 'object' || !row.id || row.status !== 'processing') return [];

const required = ['patient_id', 'doctor_id', 'appointment_date', 'start_time', 'end_time'];
const missing = required.filter(key => row[key] === undefined || row[key] === null || String(row[key]).trim() === '');
if (missing.length) {
  return [{ json: { ...row, claim_valid: false, claim_error: 'Missing required booking fields: ' + missing.join(', ') } }];
}

return [{ json: { ...row, claim_valid: true } }];

let result = $input.first()?.json ?? {};
if (result.body !== undefined) result = result.body;
if (result.data !== undefined && !Array.isArray(result)) result = result.data;
if (Array.isArray(result)) result = result[0] ?? {};

const success = result?.success === true;
const appointmentId = result?.appointment_id ?? result?.appointmentId ?? result?.id ?? null;
const request = $items('Booking Request · Normalize Claimed Request')[0]?.json ?? {};

return [{
  json: {
    request_id: request.id,
    success,
    appointment_id: success ? appointmentId : null,
    error_message: success ? null : String(result?.message ?? result?.error ?? 'Booking RPC did not return success=true'),
    booking_result: result
  }
}];

const event = $input.first()?.json ?? {};
let payload = event.payload ?? event.data?.payload ?? event.message ?? event;

if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); }
  catch { return []; }
}

const requestId = payload?.id ?? payload?.request_id ?? payload?.booking_request_id;
if (!requestId || typeof requestId !== 'string') return [];

return [{ json: { request_id: requestId } }];

let result = $input.first()?.json ?? {};
if (result.body !== undefined) result = result.body;
if (result.data !== undefined && !Array.isArray(result)) result = result.data;
if (Array.isArray(result)) result = result[0] ?? {};
const request = $items('Cancellation Request · Normalize Cancellation Request')[0]?.json ?? {};
const success = result?.success === true;
return [{ json: { request_id: request.id, success, error_message: success ? null : String(result?.message ?? result?.error ?? 'Cancellation RPC did not return success=true'), cancellation_result: result } }];

const event = $input.first()?.json ?? {};
let payload = event.payload ?? event.data?.payload ?? event.message ?? event;
if (typeof payload === 'string') { try { payload = JSON.parse(payload); } catch { return []; } }
const requestId = payload?.id ?? payload?.request_id ?? payload?.cancellation_request_id;
if (!requestId || typeof requestId !== 'string') return [];
return [{ json: { request_id: requestId } }];

let result = $input.first()?.json ?? {};
if (result.body !== undefined) result = result.body;
if (result.data !== undefined && !Array.isArray(result)) result = result.data;
const row = Array.isArray(result) ? result[0] : result;
if (!row || typeof row !== 'object' || !row.id || row.status !== 'processing') return [];
const required = ['appointment_id'];
const missing = required.filter(key => row[key] === undefined || row[key] === null || String(row[key]).trim() === '');
if (missing.length) return [{ json: { ...row, claim_valid: false, claim_error: 'Missing required cancellation fields: ' + missing.join(', ') } }];
return [{ json: { ...row, claim_valid: true } }];

const event = $input.first()?.json ?? {};
let payload = event.payload ?? event.data?.payload ?? event.message ?? event;
if (typeof payload === 'string') { try { payload = JSON.parse(payload); } catch { return []; } }
const requestId = payload?.id ?? payload?.request_id ?? payload?.rescheduling_request_id;
if (!requestId || typeof requestId !== 'string') return [];
return [{ json: { request_id: requestId } }];

let result = $input.first()?.json ?? {};
if (result.body !== undefined) result = result.body;
if (result.data !== undefined && !Array.isArray(result)) result = result.data;
const row = Array.isArray(result) ? result[0] : result;
if (!row || typeof row !== 'object' || !row.id || row.status !== 'processing') return [];
const required = ['appointment_id', 'new_appointment_date', 'new_start_time', 'new_end_time'];
const missing = required.filter(key => row[key] === undefined || row[key] === null || String(row[key]).trim() === '');
if (missing.length) return [{ json: { ...row, claim_valid: false, claim_error: 'Missing required rescheduling fields: ' + missing.join(', ') } }];
return [{ json: { ...row, claim_valid: true } }];

let result = $input.first()?.json ?? {};
if (result.body !== undefined) result = result.body;
if (result.data !== undefined && !Array.isArray(result)) result = result.data;
if (Array.isArray(result)) result = result[0] ?? {};
const request = $items('Rescheduling Request · Normalize Claimed Rescheduling Request')[0]?.json ?? {};
const success = result?.success === true;
return [{ json: { request_id: request.id, success, error_message: success ? null : String(result?.message ?? result?.error ?? 'Rescheduling RPC did not return success=true'), rescheduling_result: result } }];

const body = $items("Doctor Availability · Webhook · Verified input")[0]?.json?.body ?? {};
const action = String(body.action ?? "availability").toLowerCase();

const supportedActions = ["availability", "book"];

if (!supportedActions.includes(action)) {
  return [{
    json: {
      httpStatus: 400,
      success: false,
      action,
      message: "Unsupported action. Use 'availability' or 'book'."
    }
  }];
}

// Availability and booking both require doctor_id and date.
const required = ["doctor_id", "date"];

if (action === "book") {
  required.push("patient_id", "start_time", "end_time");
}

const missing = required.filter(
  (k) => body[k] === undefined || body[k] === null || String(body[k]).trim() === ""
);

if (missing.length) {
  return [{
    json: {
      httpStatus: 400,
      success: false,
      action,
      message: "Missing required fields: " + missing.join(", ")
    }
  }];
}

// Validate date format.
const dateString = String(body.date);

if (!/^\d{4}-\d{2}-\d{2}$/.test(dateString)) {
  return [{
    json: {
      httpStatus: 400,
      success: false,
      action,
      message: "date must use YYYY-MM-DD format."
    }
  }];
}

// Validate that the date actually exists.
const date = new Date(dateString + "T00:00:00Z");

if (
  Number.isNaN(date.getTime()) ||
  date.toISOString().slice(0, 10) !== dateString
) {
  return [{
    json: {
      httpStatus: 400,
      success: false,
      action,
      message: "date is not a valid calendar date."
    }
  }];
}

// Preserve the existing availability behavior.
const result = {
  httpStatus: 200,
  success: true,
  action,
  doctor_id: String(body.doctor_id),
  date: dateString,
  day_of_week: date.getUTCDay()
};

// Additional validation for booking requests.
if (action === "book") {
  const timePattern = /^(?:[01]\d|2[0-3]):[0-5]\d$/;
  const startTime = String(body.start_time);
  const endTime = String(body.end_time);

  if (!timePattern.test(startTime) || !timePattern.test(endTime)) {
    return [{
      json: {
        httpStatus: 400,
        success: false,
        action,
        message: "start_time and end_time must use HH:mm format."
      }
    }];
  }

  const toMinutes = (time) => {
    const [hours, minutes] = time.split(":").map(Number);
    return hours * 60 + minutes;
  };

  if (toMinutes(startTime) >= toMinutes(endTime)) {
    return [{
      json: {
        httpStatus: 400,
        success: false,
        action,
        message: "end_time must be later than start_time."
      }
    }];
  }

  result.patient_id = String(body.patient_id);
  result.start_time = startTime;
  result.end_time = endTime;
}

return [{ json: result }];

const req = $items("Doctor Availability · Validate request")[0]?.json ?? {};
if (!req.success) return [{ json: req }];

const schedules = $items("Doctor Availability · Get many rows").map(x => x.json).filter(x => x && x.id);
const appointments = $items("Doctor Availability · Get existing appointments").map(x => x.json).filter(x => x && x.id && x.status !== "cancelled");
const daySchedules = schedules.filter(s => Number(s.day_of_week) === Number(req.day_of_week) && s.is_active !== false);

if (!daySchedules.length) {
  return [{ json: { success: true, action: "availability", doctor_id: req.doctor_id, date: req.date, available_slots: [], available_count: 0, message: "No active working schedule exists for this doctor on the requested day." } }];
}
const toMinutes = (value) => {
  if (typeof value !== "string") return NaN;
  const m = value.match(/^([0-9]{2}):([0-9]{2})(?::([0-9]{2}))?/);
  if (!m) return NaN;
  const h = Number(m[1]), min = Number(m[2]), sec = Number(m[3] || 0);
  if (h > 23 || min > 59 || sec > 59) return NaN;
  return h * 60 + min + sec / 60;
};
const toTime = (mins) => {
  const whole = Math.floor(mins);
  const h = Math.floor(whole / 60);
  const m = whole % 60;
  const s = Math.round((mins - whole) * 60);
  return [h,m,s].map(v => String(v).padStart(2,"0")).join(":");
};
const busy = appointments
  .filter(a => a.appointment_date === req.date && String(a.doctor_id) === String(req.doctor_id))
  .map(a => ({ start: toMinutes(a.start_time), end: toMinutes(a.end_time) }))
  .filter(a => Number.isFinite(a.start) && Number.isFinite(a.end) && a.end > a.start);

const slots = [];
for (const schedule of daySchedules) {
  const start = toMinutes(schedule.start_time);
  const end = toMinutes(schedule.end_time);
  const duration = Number(schedule.slot_duration_minutes || 30);
  if (!Number.isFinite(start) || !Number.isFinite(end) || !Number.isFinite(duration) || duration <= 0 || end <= start) continue;
  for (let t = start; t + duration <= end; t += duration) {
    const slotEnd = t + duration;
    if (!busy.some(b => t < b.end && slotEnd > b.start)) slots.push({ start_time: toTime(t), end_time: toTime(slotEnd) });
  }
}
const unique = [...new Map(slots.map(s => [s.start_time + "|" + s.end_time, s])).values()]
  .sort((a,b) => toMinutes(a.start_time) - toMinutes(b.start_time));
return [{ json: { success: true, action: "availability", doctor_id: req.doctor_id, date: req.date, available_slots: unique, available_count: unique.length, message: "Availability calculated from active doctor schedules and non-cancelled appointments." } }];

const result = $json ?? {};
if (typeof result.success === 'boolean') {
  return [{ json: { ...result, action: 'book', httpStatus: result.success ? 200 : 409 } }];
}
return [{ json: { httpStatus: 502, success: false, action: 'book', message: result.message || result.error || 'Booking service returned an unexpected response.' } }];

const events = $items("Waiting List Matcher · Get Pending Slot Events").map(i => i.json);
const patients = $input.all().map(i => i.json);
const assigned = new Set();
const matches = [];
for (const event of events) {
  const candidates = patients.filter(p =>
    !assigned.has(p.id) &&
    p.doctor_id === event.doctor_id &&
    String(p.preferred_date).slice(0,10) === String(event.appointment_date).slice(0,10) &&
    (p.preferred_start_time == null || (
      String(event.start_time) >= String(p.preferred_start_time) &&
      String(event.end_time) <= String(p.preferred_end_time)
    ))
  ).sort((a,b) => Number(b.priority ?? 0) - Number(a.priority ?? 0) || new Date(a.created_at) - new Date(b.created_at));
  if (!candidates.length) continue;
  const patient = candidates[0];
  assigned.add(patient.id);
  matches.push({json:{...event, waiting_list_id:patient.id, patient_id:patient.patient_id, priority:patient.priority, expires_at:new Date(Date.now()+15*60*1000).toISOString()}});
}
return matches;

const claims = $input.all();
const candidates = $items("Waiting List Matcher · Select Matching Patients");
return claims.flatMap((item,index) => {
  const value = item.json.claimed;
  const ok = value === true || value === "true" || value === "t" || value === 1;
  return ok && candidates[index] ? [{json:candidates[index].json,pairedItem:{item:index}}] : [];
});

const body = $('Waiting List Response Handler · Offer Response Webhook').first().json.body ?? {};
const patient_id=$json.body?.id;
if (!patient_id) return {json:{authorized:false}};
const offer_id = String(body.offer_id ?? '').trim();
const response = String(body.response ?? '').trim().toLowerCase();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(offer_id)) throw new Error('A valid offer_id UUID is required.');
if (!['accepted','rejected'].includes(response)) throw new Error('response must be accepted or rejected.');
return {json:{authorized:true,patient_id,offer_id,response}};

const offer = $json.offer;
if (!offer || !offer.id) return {json:{offer_valid:false,success:false,message:'Offer not found, already answered, or expired.'}};
return {json:{...offer,offer_valid:true,response:$json.response}};

const visit = $('P3-02b · Get visit').first().json;
const revs = $('P3-02b · Get existing revisions').all().map(i => i.json).filter(r => r.id);
const services = $('P3-02b · Get performed services').all().map(i => i.json).filter(r => r.id);
const current = revs.find(r => r.id === visit.current_revision_id) || null;
let content = null;
if (current && current.content) {
  try { content = JSON.parse(current.content); } catch (e) { content = null; }
}
return [{ json: {
  visit,
  current_revision: current ? {
    id: current.id,
    revision_no: current.revision_no,
    author_id: current.author_id,
    created_at: current.created_at,
    content
  } : null,
  revision_count: revs.length,
  performed_services: services.filter(s => !current || s.revision_id === current.id)
} }];

function sha256(bytes) {
  const K = new Uint32Array([
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2]);
  const H = new Uint32Array([0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19]);
  const len = bytes.length;
  const total = ((len + 9 + 63) >> 6) << 6;
  const p = new Uint8Array(total);
  p.set(bytes);
  p[len] = 0x80;
  const dv = new DataView(p.buffer);
  dv.setUint32(total - 8, Math.floor(len / 0x20000000));
  dv.setUint32(total - 4, (len << 3) >>> 0);
  const w = new Uint32Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let o = 0; o < total; o += 64) {
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(o + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i-15], 7) ^ rotr(w[i-15], 18) ^ (w[i-15] >>> 3);
      const s1 = rotr(w[i-2], 17) ^ rotr(w[i-2], 19) ^ (w[i-2] >>> 10);
      w[i] = (w[i-16] + s0 + w[i-7] + s1) >>> 0;
    }
    let [a,b,c,d,e,f,g,h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0]=(H[0]+a)>>>0; H[1]=(H[1]+b)>>>0; H[2]=(H[2]+c)>>>0; H[3]=(H[3]+d)>>>0;
    H[4]=(H[4]+e)>>>0; H[5]=(H[5]+f)>>>0; H[6]=(H[6]+g)>>>0; H[7]=(H[7]+h)>>>0;
  }
  return Array.from(H).map(x => x.toString(16).padStart(8, '0')).join('');
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const MAX_BYTES = 5 * 1024 * 1024;
const item = $input.first();
const body = item.json.body || {};
const fail = (status, error) => [{ json: { valid: false, status, error } }];

if (!UUID.test(String(body.visit_id || '')) || !UUID.test(String(body.doctor_id || ''))) {
  return fail(422, 'valid_visit_id_and_doctor_id_required');
}
// n8n names multipart files file0, file1, ... so take the first binary property whatever it is called
const key = item.binary ? Object.keys(item.binary)[0] : null;
if (!key) return fail(422, 'file_required');

const buf = await this.helpers.getBinaryDataBuffer(0, key);
if (buf.length === 0) return fail(422, 'empty_file');
if (buf.length > MAX_BYTES) return fail(413, 'file_too_large_max_5mb');

let type = null;
if (buf.length >= 5 && buf.subarray(0, 5).toString('latin1') === '%PDF-') {
  type = { mime: 'application/pdf', ext: 'pdf' };
} else if (buf.length >= 8 && buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) {
  type = { mime: 'image/png', ext: 'png' };
} else if (buf.length >= 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) {
  type = { mime: 'image/jpeg', ext: 'jpg' };
}
if (!type) return fail(415, 'unsupported_file_type');

return [{
  json: {
    valid: true,
    visit_id: body.visit_id,
    doctor_id: body.doctor_id,
    size: buf.length,
    mime_type: type.mime,
    ext: type.ext,
    checksum: sha256(buf)
  },
  binary: { file: item.binary[key] }
}];

const v = $('P3-03 · Validate file').first();
const visit = $('P3-03 · Get visit').first().json;
const j = v.json;
const storage_path = j.visit_id + '/' + Date.now() + '_' + j.checksum.slice(0, 12) + '.' + j.ext;
return [{
  json: {
    visit_id: j.visit_id,
    revision_id: visit.current_revision_id,
    storage_path,
    mime_type: j.mime_type,
    checksum: j.checksum,
    uploaded_by: j.doctor_id,
    file_name: (String(v.binary.file.fileName || '').split(/[\\/]/).pop().replace(/[\u0000-\u001f\u007f\u202a-\u202e\u2066-\u2069]/gu, '').trim().slice(0, 160) || 'visit-file.' + j.ext),
    size: j.size
  },
  binary: { file: { ...v.binary.file, mimeType: j.mime_type } }
}];

const claim = $('P4-01-2-telegram-delivery · Recheck and start dispatch').item.json;
const response = $json;
const rejection = response.error?.response?.body ?? response.error?.response?.data ?? response;
let outcome = 'delivery_unknown';
if ((response.ok === true && Number.isInteger(response.result?.message_id)) || Number.isInteger(response.message_id)) {
    outcome = 'accepted';
} else if (
    (rejection.ok === false && [400, 401, 403, 404, 429].includes(rejection.error_code)) ||
    response.error === 'Forbidden: bot was blocked by the user'
) {
    outcome = 'failed';
}
return { json: { id: claim.id, claim_token: claim.claim_token, outcome } };

const x = $json;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const valid = x.action === 'invoice.create' && typeof x.request_id === 'string' && x.request_id.trim().length > 0 && x.request_id.length <= 200 && x.actor?.kind === 'staff' && uuid.test(x.actor?.id || '') && uuid.test(x.payload?.visit_id || '');
return [{json: valid ? {...x, valid: true} : {valid: false, ok: false, code: 'VALIDATION_ERROR', data: null, message: 'Invalid invoice request'}}];

const p=$('Catalog form · Prepare request').first().json; let r=$json;
if (!['create','update'].includes(p.action) || !p.service_code || p.service_code.length>100) r={ok:false,code:'VALIDATION_ERROR',data:null,message:'Choose Create or Update and enter a service code.'};
else if (p.action==='create' && r.code==='SERVICE_FOUND') r={ok:false,code:'ALREADY_EXISTS',data:null,message:'Service code already exists. Choose Update to edit it.'};
else if (p.action==='update' && r.code==='NOT_FOUND') r={ok:false,code:'NOT_FOUND',data:null,message:'Service not found. Choose Create to add it.'};
const canEdit=(p.action==='create' && r.code==='NOT_FOUND') || (p.action==='update' && r.code==='SERVICE_FOUND');
return [{json:{...r,can_edit:canEdit,result:{...r,data:p.action==='update'?r.data:null}}}];

const actor=$json.actor_id, code=$json.service_code;
if (typeof actor !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(actor) || typeof code !== 'string' || !code.trim() || code.length > 100) throw new Error('VALIDATION_ERROR: actor_id and service_code are required. Run the Service Configuration form.');
return [{json:{actor_id:actor,service_code:code}}];

const sent=$json.result ?? $json;
const error=$json.error?.response?.body ?? $json.error?.response?.data ?? $json;
const id=Number.isInteger(sent.message_id) && sent.message_id>0 ? sent.message_id : 0;
const outcome=id ? 'accepted' : error.ok === false && [400,401,403,404,429].includes(error.error_code) ? 'failed' : 'delivery_unknown';
return [{json:{outcome,id}}];
